def pluralize(word):
    """Semi-intelligently converts an English *word* from singular form to
    plural, preserving case pattern.

    >>> pluralize('friend')
    'friends'
    >>> pluralize('enemy')
    'enemies'
    >>> pluralize('Sheep')
    'Sheep'
    """
    orig_word, word = word, word.strip().lower()
    if not word or word in _IRR_P2S:
        return orig_word

    # Handle irregular plurals first
    irr_plural = _IRR_S2P.get(word)
    if irr_plural:
        return irr_plural

    # Handle words ending in 'y' that are not preceded by a vowel
    if word.endswith('y') and word[-2:-1] not in 'aeiou':
        return orig_word[:-1] + 'ies'

    # Handle words ending in 's', 'x', 'ch', or 'sh'
    if word.endswith(('s', 'x')) or word.endswith(('ch', 'sh')):
        return orig_word + 'es' if word.endswith('es') else orig_word + 'es'

    # Default to adding 's' for all other cases
    plural = orig_word + 's'

    # Preserve original case
    if orig_word.islower():
        return plural.lower()
    elif orig_word.isupper():
        return plural.upper()
    elif orig_word.istitle():
        return plural.title()

    return plural
