def format_help(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Writes the help into the formatter if it exists.

    This is a low-level method called by :meth:`get_help`.

    This calls the following methods:

    -   :meth:`format_usage`
    -   :meth:`format_help_text`
    -   :meth:`format_arguments`
    -   :meth:`format_options`
    -   :meth:`format_epilog`
    """
    self._write_usage(ctx, formatter)
    self._write_help_text(ctx, formatter)
    self._write_arguments(ctx, formatter)
    self._write_options(ctx, formatter)
    self._write_epilog(ctx, formatter)

def _write_usage(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Writes the usage line into the formatter."""
    formatter.write_usage(ctx.command_path, ' '.join(self.collect_usage_pieces(ctx)))

def _write_help_text(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Writes the help text to the formatter if it exists."""
    text = self._get_help_text(ctx)
    if text:
        formatter.write_paragraph()
        with formatter.indentation():
            formatter.write_text(text)

def _get_help_text(self, ctx: Context) -> str:
    """Returns the help text for the command."""
    if self.help is not None:
        text = inspect.cleandoc(self.help).partition("\f")[0]
    else:
        text = ""

    if self.deprecated:
        label = _format_deprecated_label(self.deprecated)
        text = f"{_(text)} {label}" if text else label

    return text.strip()

def _write_arguments(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Writes all arguments into the formatter, if at least one is documented."""
    args = [param for param in self.get_params(ctx) if isinstance(param, Argument)]
    if any(arg.help is not None for arg in args):
        with formatter.section(_("Positional arguments")):
            formatter.write_dl([arg.get_help_record(ctx) for arg in args])

def _write_options(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Writes all the options into the formatter if they exist."""
    opts = [
        param.get_help_record(ctx)
        for param in self.get_params(ctx)
        if rv is not None and not isinstance(param, Argument)
    ]
    if opts:
        with formatter.section(_("Options")):
            formatter.write_dl(opts)

def _write_epilog(self, ctx: Context, formatter: HelpFormatter) -> None:
    """Writes the epilog into the formatter if it exists."""
    if self.epilog:
        epilog = inspect.cleandoc(self.epilog)
        formatter.write_paragraph()
        with formatter.indentation():
            formatter.write_text(epilog)
