import re
from typing import Match, Optional

def extract_code_and_info(m: Match[str]) -> Tuple[str, str, str]:
    spaces = m.group("fenced_1")
    marker = m.group("fenced_2")
    info = m.group("fenced_3")
    return spaces, marker, info

def find_end_marker(state: BlockState, marker: str, start_position: int) -> Optional[Match[str]]:
    end_pattern = re.compile(
        r"^ {0,3}" + re.escape(marker) + r"{" + str(len(marker)) + r",}[ \t]*(?:\n|$)", re.M
    )
    return end_pattern.search(state.src, start_position)

def trim_code(code: str, spaces: str) -> str:
    if spaces and code:
        trim_pattern = re.compile("^ {0," + str(len(spaces)) + "}", re.M)
        return trim_pattern.sub("", code)
    return code

def create_token(info: str, code: str, marker: str) -> dict:
    token = {"type": "block_code", "raw": code, "style": "fenced", "marker": marker}
    if info:
        token["attrs"] = {"info": info.strip()}
    return token

class BlockParser(Parser[BlockState]):
    def parse_fenced_code(self, m: Match[str], state: BlockState) -> Optional[int]:
        """Parse token for fenced code block. A fenced code block is started with
        3 or more backtick(`) or tilde(~).

        An example of a fenced code block:

        .. code-block:: markdown

            ```python
            def markdown(text):
                return mistune.html(text)
            ```
        """
        spaces, marker, info = extract_code_and_info(m)
        end_match = find_end_marker(state, marker, m.end() + 1)

        if not end_match:
            code = state.src[m.end():]
            end_pos = state.cursor_max
        else:
            code = state.src[m.end():end_match.start()]
            end_pos = end_match.end()

        code = trim_code(code, spaces)
        token = create_token(info, code, marker)
        state.append_token(token)
        return end_pos
