import re
from typing import Optional

from mistune.block_parser import BlockParser, BlockState
from mistune.helpers import _ESCAPE_CHAR_RE

class BlockParser(BlockParser):
    def parse_fenced_code(self, m: re.Match[str], state: BlockState) -> Optional[int]:
        """Parse token for fenced code block. A fenced code block is started with
        3 or more backtick(`) or tilde(~).

        An example of a fenced code block:

        .. code-block:: markdown

            ```python
            def markdown(text):
                return mistune.html(text)
            ```
        """
        spaces = m.group("fenced_1")
        marker = m.group("fenced_2")
        info = m.group("fenced_3")

        if self._contains_backtick_in_info(info, marker):
            return None

        end_marker = self._create_end_marker_regex(marker)
        cursor_start = m.end() + 1

        m2 = end_marker.search(state.src, cursor_start)
        if m2:
            code = state.src[cursor_start : m2.start()]
            end_pos = m2.end()
        else:
            code = state.src[cursor_start:]
            end_pos = state.cursor_max

        if spaces and code:
            code = self._trim_leading_spaces(code, len(spaces))

        token = {
            "type": "block_code",
            "raw": code,
            "style": "fenced",
            "marker": marker,
        }
        if info:
            token["attrs"] = {"info": self._unescape_and_strip_info(info)}

        state.append_token(token)
        return end_pos

    @staticmethod
    def _contains_backtick_in_info(info: str, marker: str) -> bool:
        if info and marker[0] == "`":
            return info.find("`") != -1
        return False

    @staticmethod
    def _create_end_marker_regex(marker: str) -> re.Pattern[str]:
        return re.compile(
            r"^ {0,3}" + re.escape(marker) + r"{" + str(len(marker)) + r",}[ \t]*(?:\n|$)", re.M
        )

    @staticmethod
    def _trim_leading_spaces(code: str, num_spaces: int) -> str:
        trim_pattern = re.compile("^ {0," + str(num_spaces) + "}", re.M)
        return trim_pattern.sub("", code)

    @staticmethod
    def _unescape_and_strip_info(info: str) -> str:
        return _ESCAPE_CHAR_RE.sub("\\1", info).strip()
