def parse_ref_link(self, m: Match[str], state: BlockState) -> Optional[int]:
    """Parse link references and save the link information into ``state.env``."""
    end_pos = state.append_paragraph()
    if end_pos:
        return end_pos

    label = m.group("reflink_1").strip()
    key = label.upper()
    if not key:
        return None

    href, href_pos = parse_link_href(state.src, m.end(), block=True, max_nested_level=self.max_nested_level)
    if href is None:
        return None

    blank_pos = _find_next_blank_line(state, href_pos, self.BLANK_LINE)
    max_pos = blank_pos if blank_pos is not None else state.cursor_max

    title, title_pos = parse_link_title(state.src, href_pos, max_pos)
    if title_pos:
        title_pos = _skip_blank_lines(state.src, title_pos)

    if title_pos is None:
        href_pos = _skip_blank_lines(state.src, href_pos)

    end_pos = title_pos or href_pos
    if not end_pos:
        return None

    if key not in state.env["ref_links"]:
        href = unescape_char(href)
        data = {"url": escape_url(href), "label": label}
        if title:
            data["title"] = title
        state.env["ref_links"][key] = data
    return end_pos

def _skip_blank_lines(src: str, pos: int) -> int:
    """Skip over any blank lines starting at `pos`."""
    while pos < len(src):
        m = _BLANK_TO_LINE.match(src, pos)
        if m:
            pos = m.end()
        else:
            break
    return pos
