# Helper function to get or create footnote references
def get_or_create_footnote_reference(state: "InlineState", key: str) -> int:
    ref = state.env.get("ref_footnotes")
    if ref and key in ref:
        notes = state.env.get("footnotes", [])
        indexes = state.env.setdefault("footnote_indexes", {})
        if key not in indexes:
            notes.append(key)
            indexes[key] = len(notes) - 1
            state.env["footnotes"] = notes
        return indexes[key]
    return None

def parse_inline_footnote(inline: "InlineParser", m: Match[str], state: "InlineState") -> int:
    key = normalize_footnote_key(m.group('footnote_key'))
    index = get_or_create_footnote_reference(state, key)

    if index is not None:
        state.append_token({"type": "footnote_ref", "raw": key, "attrs": {"index": index + 1}})
    else:
        state.append_token({"type": "text", "raw": m.group(0)})

    return m.end()
