        state.env["inline_images"] = []
        rendered_tokens = self.render_tokens(tokens, state)
        references = self.render_referrences(state)
        cleaned_references = join_with_double_newlines(references)
        final_output = rendered_tokens + cleaned_references + "\n"
        trimmed_output = remove_trailing_spaces(final_output)
        return trim_extra_newlines(trimmed_output)

def trim_extra_newlines(text: str) -> str:
    """Trim extra newlines at the beginning and end of the text."""
    lines = text.split('\n')
    while lines and lines[0].strip() == '':
        lines.pop(0)
    while lines and lines[-1].strip() == '':
        lines.pop()
    return '\n'.join(lines)
