_VERSION_TAG = '%s-%s%s-%s' % (
    platform.python_implementation(),
    sys.version_info[0],
    sys.version_info[1],
    _PICKLE_VERSION
)

_default_cache_path = Path.home() / '.cache' / 'parso'
if platform.system().lower() == 'windows':
    _default_cache_path = Path(os.getenv('LOCALAPPDATA')) / 'Parso' / 'Parso'
elif platform.system().lower() == 'darwin':
    _default_cache_path = Path.home() / 'Library' / 'Caches' / 'Parso'

_CACHE_CLEAR_THRESHOLD = 60 * 60 * 24

def _get_cache_clear_lock_path(cache_path: Path = None) -> Path:
    cache_path = cache_path or _default_cache_path
    return cache_path / "PARSO-CACHE-LOCK"

parser_cache: Dict[str, Any] = {}

class _NodeCacheItem:
    def __init__(self, node, lines, change_time=None):
        self.node = node
        self.lines = lines
        self.change_time = change_time or time.time()
        self.last_used = self.change_time

def _remove_cache_and_update_lock(cache_path: Path = None) -> bool:
    cache_path = cache_path or _default_cache_path
    lock_path = _get_cache_clear_lock_path(cache_path)

    try:
        clear_lock_time = os.path.getmtime(lock_path)
    except FileNotFoundError:
        clear_lock_time = None

    if clear_lock_time is None or clear_lock_time + _CACHE_CLEAR_THRESHOLD <= time.time():
        if not _touch(lock_path):
            return False

        clear_inactive_cache(cache_path=cache_path)

    return True

def _touch(path: Path) -> bool:
    try:
        os.utime(path, None)
    except FileNotFoundError:
        try:
            with open(path, 'a'):
                pass
        except (OSError, IOError):
            return False
    return True

def clear_inactive_cache(cache_path: Path = None, inactivity_threshold: int = _CACHED_FILE_MAXIMUM_SURVIVAL) -> bool:
    if cache_path is None:
        cache_path = _default_cache_path
    if not cache_path.exists():
        return False

    for dirname in os.listdir(cache_path):
        version_path = cache_path / dirname
        if not version_path.is_dir():
            continue

        for file in os.scandir(version_path):
            if file.stat().st_atime + inactivity_threshold <= time.time():
                try:
                    os.remove(file.path)
                except OSError:
                    continue

    return True
