def visit_leaf(self, leaf):
    if leaf.type == 'error_leaf':
        self._handle_error_leaf(leaf)
    elif leaf.value == ':':
        self._handle_colon_in_definition(leaf)

    # Apply rules based on type and value
    self._apply_rules_by_type(leaf)
    self._apply_rules_by_value(leaf)

    return leaf.prefix + leaf.value

def _handle_error_leaf(self, leaf):
    if leaf.token_type in ('INDENT', 'ERROR_DEDENT'):
        spacing = list(leaf.get_next_leaf()._split_prefix())[-1]
        message = 'unexpected indent' if leaf.token_type == 'INDENT' else 'unindent does not match any outer indentation level'
        self._add_indentation_error(spacing, message)
    else:
        if leaf.value.startswith('\\'):
            message = 'unexpected character after line continuation character'
        else:
            match = re.match('\\w{,2}("{1,3}|\'{1,3})', leaf.value)
            if match is None:
                message = 'invalid syntax'
                if self.version >= (3, 9) and leaf.value in _get_token_collection(self.version).always_break_tokens:
                    message = "f-string: " + message
            else:
                if len(match.group(1)) == 1:
                    message = 'EOL while scanning string literal'
                else:
                    message = 'EOF while scanning triple-quoted string literal'
        self._add_syntax_error(leaf, message)

def _handle_colon_in_definition(self, leaf):
    parent = leaf.parent
    if parent.type in ('classdef', 'funcdef'):
        self.context = self.context.add_context(parent)

def _apply_rules_by_type(self, leaf):
    for rule in self._rule_type_instances.get(leaf.type, []):
        rule.feed_node(leaf)

def _apply_rules_by_value(self, leaf):
    for rule in self._rule_value_instances.get(leaf.value, []):
        rule.feed_node(leaf)
