def _handle_error_leaf(normalizer, leaf):
    if leaf.token_type in ('INDENT', 'ERROR_DEDENT'):
        spacing = list(leaf.get_next_leaf()._split_prefix())[-1]
        if leaf.token_type == 'INDENT':
            message = 'unexpected indent'
        else:
            message = 'unindent does not match any outer indentation level'
        _add_indentation_error(normalizer, spacing, message)
    else:
        if leaf.value.startswith('\\'):
            message = 'unexpected character after line continuation character'
        else:
            match = re.match('\\w{,2}("{1,3}|\'{1,3})', leaf.value)
            if match is None:
                message = 'invalid syntax'
                if (
                    normalizer.version >= (3, 9)
                    and leaf.value in _get_token_collection(
                        normalizer.version
                    ).always_break_tokens
                ):
                    message = "f-string: " + message
            else:
                if len(match.group(1)) == 1:
                    message = 'EOL while scanning string literal'
                else:
                    message = 'EOF while scanning triple-quoted string literal'
        _add_syntax_error(normalizer, leaf, message)
    return ''

def _handle_colon_in_class_or_func_def(normalizer, leaf):
    parent = leaf.parent
    if parent.type in ('classdef', 'funcdef'):
        normalizer.context = normalizer.context.add_context(parent)

def visit_leaf(self, leaf):
    if leaf.type == 'error_leaf':
        return _handle_error_leaf(self, leaf)
    elif leaf.value == ':':
        _handle_colon_in_class_or_func_def(self, leaf)

    # The rest is rule based.
    return super().visit_leaf(leaf)
