            _handle_indentation_error(self, leaf, list(leaf.get_next_leaf()._split_prefix())[-1])
        else:
            _handle_syntax_error(self, leaf)
        return ''
    elif leaf.value == ':':
        parent = leaf.parent
        if parent.type in ('classdef', 'funcdef'):
            self.context = self.context.add_context(parent)

    # The rest is rule based.
    return super().visit_leaf(leaf)
