def _parse_atom(self) -> Tuple[NFAState, NFAState]:
    # atom: '(' rhs ')' | NAME | STRING
    if self.value == "(":
        return self._parse_parenthesized_expression()
    elif self.type in (PythonTokenTypes.NAME, PythonTokenTypes.STRING):
        return self._parse_identifier_or_string()
    else:
        self._raise_error("expected (...) or NAME or STRING, got %s/%s", self.type, self.value)

def _parse_parenthesized_expression(self) -> Tuple[NFAState, NFAState]:
    self._gettoken()
    a, z = self._parse_rhs()
    self._expect_token(PythonTokenTypes.OP, ')')
    return a, z

def _parse_identifier_or_string(self) -> Tuple[NFAState, NFAState]:
    a = NFAState(self._current_rule_name)
    z = NFAState(self._current_rule_name)
    a.add_arc(z, self.value)
    self._gettoken()
    return a, z

def _expect_token(self, expected_type: str, expected_value: str):
    if self.type != expected_type:
        self._raise_error(f'expected {expected_type}, got {self.type} [{self.value}]')
    if expected_value is not None and self.value != expected_value:
        self._raise_error(f'expected {expected_value}, got {self.value}')
    value = self.value
    self._gettoken()
```

