def _parse(self, until_line):
    """
    Parses at least until the given line, but might just parse more until a
    valid state is reached.
    """
    while until_line > self._nodes_tree.parsed_until_line:
        self._increment_parser_count()
        parsed_until_line = self._nodes_tree.parsed_until_line
        lines_to_parse = self._lines_after(parsed_until_line)
        tokens = self._tokenize_diff(lines_to_parse, until_line, line_offset=parsed_until_line)
        self._update_active_parser()
        node = self._parse_tokens(tokens)
        nodes = node.children

        self._add_parsed_nodes(nodes)
        self._adjust_indentation_if_needed()

        self._log_parsing_progress(node)

        assert self._parsed_until_line_has_changed(last_until_line), last_until_line
        last_until_line = self._nodes_tree.parsed_until_line

def _increment_parser_count(self):
    self._parser_count += 1

def _lines_after(self, parsed_until_line):
    return self._parser_lines_new[parsed_until_line:]

def _tokenize_diff(self, lines, until_line, line_offset):
    return self._diff_tokenize(lines, until_line, line_offset=line_offset)

def _update_active_parser(self):
    self._active_parser = Parser(self._pgen_grammar, error_recovery=True)

def _parse_tokens(self, tokens):
    return self._active_parser.parse(tokens=tokens)

def _add_parsed_nodes(self, nodes):
    self._nodes_tree.add_parsed_nodes(nodes, self._keyword_token_indents)

def _adjust_indentation_if_needed(self):
    if self._replace_tos_indent is not None:
        self._nodes_tree.indents[-1] = self._replace_tos_indent

def _log_parsing_progress(self, node):
    LOG.debug(
        'parse_part from %s to %s (to %s in part parser)',
        node.children[0].get_start_pos_of_prefix()[0],
        self._nodes_tree.parsed_until_line,
        node.end_pos[0] - 1
    )

def _parsed_until_line_has_changed(self, last_until_line):
    return last_until_line != self._nodes_tree.parsed_until_line
