        pos = start + 1
        closers = [")"]
        pairs = {"(": ")", "[": "]", "{": "}"}
        error = "Unterminated attribute arguments"

        while pos < len(text):
            ch = text[pos]

            if self._is_comment(ch):
                pos = self._skip_comment(pos)
                continue

            if self._is_quoted_literal(ch):
                pos = self._skip_quoted_literal(ch, pos)
                continue

            if ch in pairs:
                closers.append(pairs[ch])
            elif ch in ")]}":
                if ch != closers[-1]:
                    error = "Mismatched delimiter in attribute arguments"
                    break
                closers.pop()
                if not closers:
                    end2 = pos + 1
                    value = self._lexdata[start:end2]
                    tok2 = self._make_token('ATTRIBUTE_ARGUMENTS', value, start)
                    self._update_line_info(tok2)
                    self._pos = end2
                    tok = tok2
                    tok.value = tok.value[1:-1]
                    return tok

            pos += 1

        self._error(error, start)
        self._pos = len(text)
        return None

