        if text[pos+1] == '*':
            end = text.find("*/", pos + 2)
        else:
            end = text.find("\n", pos + 2)
        return end + 2 if end >= 0 else len(text)

    def _is_quoted_literal(self, ch: str) -> bool:
        return ch in {'"', "'"}

    def _skip_quoted_literal(self, quote: str, pos: int) -> int:
        pos += 1
        while pos < len(text) and text[pos] not in {quote, "\n"}:
            pos += 2 if text[pos] == "\\" else 1
        return pos + 1 if pos < len(text) and text[pos] == quote else len(text)

