def _parse_attribute_specifier_sequence(self) -> list[c_ast.AttributeSpecifier]:
    attribute_groups = []

    while self._peek_type() == "ATTRIBUTE_BEGIN":
        opening_token = self._consume_token()
        if opening_token is None:
            self._parse_error('At end of input', self.clex.filename)

        if opening_token is not self._typedef_checked_token:
            self._classify_identifier(opening_token)

        if self._dialect != "c23":
            self._parse_error("Attributes require C23", self._tok_coord(opening_token))

        attributes = self._parse_attributes()

        self._expect("ATTRIBUTE_END")

        attribute_groups.append(
            c_ast.AttributeSpecifier(attributes, self._tok_coord(opening_token))
        )

    return attribute_groups

def _parse_attributes(self) -> list[c_ast.Attribute]:
    attributes = []

    while self._peek_type() != "ATTRIBUTE_END":
        if self._accept("COMMA"):
            continue

        name = self._parse_identifier_or_typeid()
        namespace = None

        if self._accept("COLONCOLON"):
            namespace = name.name
            name = self._parse_identifier_or_typeid()

        arguments = self._accept("ATTRIBUTE_ARGUMENTS")

        attributes.append(
            c_ast.Attribute(
                name.name,
                namespace,
                arguments.value if arguments is not None else None,
                name.coord,
            )
        )

        if not self._accept("COMMA"):
            break

    return attributes
