def _parse_parameter_type_list(self) -> c_ast.ParamList:
    def parse_single_param():
        return self._parse_parameter_declaration()

    def parse_variadic_params():
        ell_tok = self._accept("ELLIPSIS")
        if ell_tok:
            coord = self._tok_coord(ell_tok)
            if self._dialect != "c23":
                self._parse_error("Ellipsis-only parameter lists require C23", coord)
            return [c_ast.EllipsisParam(coord)]
        return []

    def parse_regular_params():
        params = []
        while self._peek_type() == 'COMMA' and self._peek_type(2) != 'ELLIPSIS':
            self._advance()
            params.append(parse_single_param())
        return params

    def parse_final_ellipsis_param():
        if self._peek_type() == "COMMA" and self._peek_type(2) == "ELLIPSIS":
            self._advance()
            ell_tok = self._advance()
            return [c_ast.EllipsisParam(self._tok_coord(ell_tok))]
        return []

    ellipsis_only = parse_variadic_params()
    regular_params = parse_regular_params()
    final_ellipsis = parse_final_ellipsis_param()

    params = regular_params + final_ellipsis
    if ellipsis_only:
        params = ellipsis_only + params

    return c_ast.ParamList(params, coord=self._tok_coord(params[0]) if params else None)
