def FUNCTIONDEF(self, node):
    self._handle_decorators(node.decorator_list, node)

    with self._type_param_scope(node):
        self._process_lambda(node)

    self.addBinding(node, FunctionDefinition(node.name, node))

    if self.withDoctest and not self._in_doctest() and not isinstance(self.scope, FunctionScope):
        self._defer_function(self._handle_doctests, node)

def _handle_decorators(self, decorators, node):
    for deco in decorators:
        self.handleNode(deco, node)

def _process_lambda(self, node):
    self.LAMBDA(node)

def _defer_function(self, func, *args, **kwargs):
    self._deferred.append((func, self.scopeStack[:], self.offset))

def _handle_doctests(self, node):
    try:
        (docstring, node_lineno) = self.getDocstring(node.body[0])
        examples = docstring and _doctest_parser()(docstring)
    except (ValueError, IndexError):
        return

    if not examples:
        return

    saved_stack = self.scopeStack
    self.scopeStack = [self.scopeStack[0]]
    node_offset = self.offset or (0, 0)

    with self.in_scope(DoctestScope):
        if '_' not in self.scopeStack[0]:
            self.addBinding(None, Builtin('_'))

        for example in examples:
            try:
                tree = ast.parse(example.source, "<doctest>")
            except SyntaxError as e:
                position = (node_lineno + example.lineno + e.lineno,
                            example.indent + 4 + (e.offset or 0))
                self.report(messages.DoctestSyntaxError, node, position)
            else:
                self.offset = (node_offset[0] + node_lineno + example.lineno,
                               node_offset[1] + example.indent + 4)
                self.handleChildren(tree)
                self.offset = node_offset

    self.scopeStack = saved_stack
