import re
from pygments.filter import Filter
from pygments.token import Keyword, Name, Whitespace, Error
from pygments.util import get_choice_opt, get_list_opt, get_int_opt, get_bool_opt, string_to_tokentype, issubclass

class KeywordCaseFilter(Filter):
    """Convert keywords to lowercase or uppercase or capitalize them.

    This means first letter uppercase, rest lowercase.

    This can be useful e.g. if you highlight Pascal code and want to adapt the
    code to your styleguide.

    Options accepted:

    `case` : string
       The casing to convert keywords to. Must be one of ``'lower'``,
       ``'upper'`` or ``'capitalize'``.  The default is ``'lower'``.
    """

    def __init__(self, **options):
        super().__init__(**options)
        self.case = self._get_case_option(options)

    @staticmethod
    def _get_case_option(options):
        cases = ['lower', 'upper', 'capitalize']
        case_str = options.get('case', 'lower').lower()
        if case_str not in cases:
            raise ValueError(f'Invalid case option: {case_str}. Must be one of {cases}')
        return getattr(str, case_str)

    def filter(self, lexer, stream):
        for ttype, value in stream:
            if ttype in Keyword:
                yield ttype, self.case(value)
            else:
                yield ttype, value
