class SymbolFilter(Filter):
    """Replace LaTeX symbols with Unicode characters.

    Options accepted:

    `lang` : string
       The language to use for symbol mapping. Must be one of ``'isabelle'`` or
       ``'latex'``.  The default is ``'isabelle'``.
    """

    def __init__(self, **options):
        Filter.__init__(self, **options)
        allowed = ['isabelle', 'latex']
        string = options.get('lang', 'isabelle').lower()
        if string not in allowed:
            raise OptionError('Value for option {} must be one of {}'.format('lang', ', '.join(map(str, allowed))))
        lang = string
        self.symbols = self._get_symbol_mapping(lang)

    def _get_symbol_mapping(self, lang):
        if lang == 'isabelle':
            return {
                '\\<zero>'                 : '\U0001d7ec',
                '\\<one>'                  : '\U0001d7ed',
                # ... (other mappings omitted for brevity) ...
                '\\<zz>'                   : '\U0001d537',
            }
        elif lang == 'latex':
            return {
                '\\ominus'               : '\U00002296',
                '\\oslash'               : '\U00002298',
                # ... (other mappings omitted for brevity) ...
                '\\textdegree'           : '\U000000b0',
            }
        else:
            raise ValueError(f"Unsupported language: {lang}")

    def filter(self, lexer, stream):
        for ttype, value in stream:
            if value in self.symbols:
                yield ttype, self.symbols[value]
            else:
                yield ttype, value
