class RawTokenFormatter(Formatter):
    r"""
    Format tokens as a raw representation for storing token streams.

    The format is ``tokentype<TAB>repr(tokenstring)\n``. The output can later
    be converted to a token stream with the `RawTokenLexer`, described in the
    :doc:`lexer list <lexers>`.

    Only two options are accepted:

    `compress`
        If set to ``'gz'`` or ``'bz2'``, compress the output with the given
        compression algorithm after encoding (default: ``''``).
    `error_color`
        If set to a color name, highlight error tokens using that color.  If
        set but with no value, defaults to ``'red'``.

        .. versionadded:: 0.11

    """
    name = 'Raw tokens'
    aliases = ['raw', 'tokens']
    filenames = ['*.raw']

    unicodeoutput = False

    def __init__(self, **options):
        super().__init__(**options)
        self.encoding = 'ascii'
        self.compress = get_choice_opt(options, 'compress', ['', 'none', 'gz', 'bz2'], '')
        self.error_color = options.get('error_color', None)
        if self.error_color is True:
            self.error_color = 'red'
        self._validate_error_color()

    def _validate_error_color(self):
        if self.error_color is not None:
            try:
                colorize(self.error_color, ' ')
            except KeyError:
                raise ValueError(f"Invalid color {self.error_color!r} specified")

    def format(self, tokensource, outfile):
        try:
            outfile.write(b'')
        except TypeError:
            raise TypeError('The raw tokens formatter needs a binary '
                            'output file')

        compressor = self._get_compressor(outfile)
        write = compressor.write
        flush = compressor.close if self.compress else outfile.flush

        for ttype, value in tokensource:
            line = b"%r\t%r\n" % (ttype, value)
            if self.error_color and ttype is Token.Error:
                write(colorize(self.error_color, line.decode()).encode())
            else:
                write(line)
        flush()

    def _get_compressor(self, outfile):
        if self.compress == 'gz':
            import gzip
            return gzip.GzipFile('', 'wb', 9, outfile)
        elif self.compress == 'bz2':
            import bz2
            return bz2.BZ2Compressor(9)
        return outfile
