def _align_cell_veritically(cell_lines, nlines, width, align):
    if align == 'top':
        cell_lines += [' '] * (nlines - len(cell_lines))
    elif align == 'middle':
        padding_top = (nlines - len(cell_lines)) // 2
        padding_bottom = nlines - len(cell_lines) - padding_top
        cell_lines = [' '] * padding_top + cell_lines + [' '] * padding_bottom
    elif align == 'bottom':
        cell_lines = [' '] * (nlines - len(cell_lines)) + cell_lines
    else:
        raise ValueError(f"Invalid alignment: {align}")

    return [cell_line.ljust(width) for cell_line in cell_lines]

def _pad_row(row, pad):
    return [cell.rjust(pad) for cell in row]

def _build_row(row, widths, alignments, format_spec):
    return format_spec.join(cell.ljust(width) for cell, width, align in zip(row, widths, alignments))

def _append_multiline_row(
    lines, padded_multiline_cells, padded_widths, colaligns, rowfmt, pad, rowalign=None
):
    colwidths = [w - 2 * pad for w in padded_widths]
    cells_lines = [c.splitlines() for c in padded_multiline_cells]
    nlines = max(map(len, cells_lines))  # number of lines in the row

    cells_lines = [
        _align_cell_veritically(cl, nlines, w, rowalign) for cl, w in zip(cells_lines, colwidths)
    ]

    lines_cells = [[cl[i] for cl in cells_lines] for i in range(nlines)]

    for ln in lines_cells:
        padded_ln = _pad_row(ln, pad)
        lines.append(_build_row(padded_ln, colwidths, colaligns, rowfmt))

    return lines
