def _change_splitlevel(self, ttype, value):
    """Get the new split level (increase, decrease or remain equal)"""

    if self._handle_semicolon(ttype, value):
        return 0

    if self._handle_parentheses(ttype, value):
        return 0

    if ttype not in T.Keyword:
        return 0

    unified = value.upper()

    if self._handle_ddl_create(ttype, unified):
        return 0

    if self._handle_declare_block(ttype, unified):
        return 0

    if self._handle_begin_block(ttype, unified):
        return 0

    if self._handle_transaction_keyword(ttype, unified):
        return 0

    if self._handle_nested_blocks(unified):
        return 0

    if self._handle_closing_keywords(unified):
        return 0

    return 0

def _handle_semicolon(self, ttype, value):
    if ttype is T.Punctuation and value == ';':
        self._unconfirmed_start = None
        if self._seen_begin:
            self._seen_begin = False
            if self._block_stack and self._block_stack[-1] == 'BEGIN':
                self._block_stack.pop()
                return True
        return True
    return False

def _handle_parentheses(self, ttype, value):
    if ttype is T.Punctuation and value == '(':
        self._parenthesis_level += 1
        return True
    elif ttype is T.Punctuation and value == ')':
        self._parenthesis_level = max(0, self._parenthesis_level - 1)
        return True
    return False

def _handle_ddl_create(self, ttype, unified):
    if ttype is T.Keyword.DDL and unified.startswith('CREATE'):
        self._is_create = True
        return True
    return False

def _handle_declare_block(self, ttype, unified):
    if unified == 'DECLARE' and self._is_create and not self._block_stack:
        self._block_stack.append('DECLARE')
        return True
    return False

def _handle_begin_block(self, ttype, unified):
    if unified == 'BEGIN':
        self._seen_begin = True
        if self._block_stack and self._block_stack[-1] == 'DECLARE':
            self._block_stack.pop()
            self._block_stack.append('BEGIN')
            return True
        else:
            self._block_stack.append('BEGIN')
            return True
    return False

def _handle_transaction_keyword(self, ttype, unified):
    if self._seen_begin and (ttype is T.Keyword or ttype is T.Name) and unified in ('TRANSACTION', 'WORK', 'TRAN', 'DISTRIBUTED', 'DEFERRED', 'IMMEDIATE', 'EXCLUSIVE'):
        self._seen_begin = False
        if self._block_stack and self._block_stack[-1] == 'BEGIN':
            self._block_stack.pop()
            return True
        return True
    return False

def _handle_nested_blocks(self, unified):
    if 'BEGIN' in self._block_stack:
        return self._handle_nested_block(unified)
    return False

def _handle_closing_keywords(self, unified):
    if unified in ('END IF', 'END FOR', 'END WHILE', 'END LOOP', 'END CASE', 'END'):
        if self._block_stack and self._block_stack[-1] in ('IF', 'FOR', 'WHILE', 'LOOP', 'CASE'):
            self._block_stack.pop()
            return True
        if self._block_stack:
            self._block_stack.pop()
