        """Check for nested loop or control structures inside a block"""
        nested_keywords = {
            'FOR': ['FOR'],
            'WHILE': ['WHILE'],
            'LOOP': ['LOOP', 'FOR', 'WHILE'],
            'DO': ['LOOP'],
            'IF': ['IF'],
            'CASE': ['CASE']
        }
        if unified in nested_keywords:
            if self._unconfirmed_start in nested_keywords[unified]:
                self._block_stack.append(self._unconfirmed_start)
                self._unconfirmed_start = None
                return 1
            if unified in nested_keywords[self._unconfirmed_start]:
                self._block_stack.append(unified)
                return 1
        return None

