    if idx is None:
        return None, None

    def is_valid_token(token):
        return not ((skip_ws and token.is_whitespace)
                    or (skip_cm and imt(token, t=T.Comment, i=Comment)))

    if _reverse:
        for token in reversed(self.tokens[:idx]):
            if is_valid_token(token):
                return token.idx, token
    else:
        for token in self.tokens[idx+1:]:
            if is_valid_token(token):
