def should_emit_header(table: Table, key: Key, prefix: str | None) -> bool:
    display_name = table.display_name
    if display_name is not None:
        return True

    _key = key.as_string()
    if prefix is not None:
        _key = prefix + "." + _key

    has_non_table_values = any(not isinstance(v2, (Table, AoT, Whitespace, Null)) for _, v2 in table.value.body)
    has_dotted_keys = any(k2 is not None and k2.is_dotted() for k2, v2 in table.value.body if isinstance(v2, Table))

    return not table.is_super_table() or (has_non_table_values and not key.is_dotted()) or (has_dotted_keys and not key.is_dotted())

def render_table_header(table: Table, key: Key, prefix: str | None) -> str:
    open_bracket, close_bracket = "[", "]"
    if table.is_aot_element():
        open_bracket, close_bracket = "[[", "]]"

    newline_in_table_trivia = "\n" if "\n" not in table.trivia.trail and len(table.value) > 0 else ""

    return (
        f"{table.trivia.indent}"
        f"{open_bracket}"
        f"{decode(key.as_string() if table.display_name is None else table.display_name)}"
        f"{close_bracket}"
        f"{table.trivia.comment_ws}"
        f"{decode(table.trivia.comment)}"
        f"{table.trivia.trail}"
        f"{newline_in_table_trivia}"
    )

def render_empty_aot(path: list[str], aot: AoT) -> str:
    return "\n".join(f"[{'] ['.join(path)}]" for _ in range(len(aot)))

def _render_table(self, key: Key, table: Table, prefix: str | None = None) -> str:
    cur = ""

    if should_emit_header(table, key, prefix):
        cur += render_table_header(table, key, prefix)

    if cur.strip(" ") and not cur.strip(" ").endswith("\n") and "\n" not in table.trivia.indent:
        cur += "\n"

    if should_emit_header(table, key, prefix):
        for path, aot in _header_less_aots(table.value.body):
            cur += render_empty_aot(path, aot)

    for k, v in table.value.body:
        if k is not None and _is_empty_aot(v):
            continue
        elif isinstance(v, Table):
            if cur.strip(" ") and not cur.strip(" ").endswith("\n") and "\n" not in v.trivia.indent:
                cur += "\n"
            assert k is not None
            if v.is_super_table():
                if k.is_dotted() and not key.is_dotted():
                    cur += self._render_table(k, v)
                else:
                    cur += self._render_table(k, v, prefix=prefix)
            else:
