        return length

def determine_indent_and_comma(self, idx: int, pos: int, length: int) -> tuple[Whitespace | None, Whitespace | None]:
    default_indent = " "
    if pos < length:
        last_item = self._value[idx]
        if not last_item.is_whitespace():
            default_indent = last_item.indent
    else:
        if idx >= 1 and self._value[idx - 1].is_whitespace():
            idx -= 1
            default_indent = "\n    "

    indent = get_indent_from_next_item(self, idx)
    comma = get_comma_for_new_item(self, idx, pos, length, indent)

    if indent is not None and "," in indent.s:
