def append(self, key: Key | str | None, _item: Any) -> InlineTable:
    """
    Appends a (key, item) to the table.
    """
    # Ensure the item is wrapped in an Item object if necessary
    if not isinstance(_item, Item):
        _item = item(_item, _parent=self)

    # Validate that inline tables cannot contain tables
    if isinstance(_item, Table):
        raise ValueError('Inline tables cannot contain a table')

    # Adjust trivia for the item based on the previous item's state
    if not isinstance(_item, (Whitespace, Comment)):
        if not _item.trivia.indent and len(self._value) > 0 and not self._new:
            _item.trivia.indent = " "
        if _item.trivia.comment:
            _item.trivia.comment = ""

    # Append the key and item to the internal value list
    self._value.append(key, _item)

    # Handle setting the key in the dictionary representation if provided
    if isinstance(key, Key):
        key = key.key

    if key is not None:
        dict.__setitem__(self, key, _item)

