def _parse_value(self) -> Item:
    """
    Attempts to parse a value at the current position.
    """
    self.mark()
    c = self._current
    trivia = Trivia()

    if c == StringType.SLB.value:
        return self._parse_string(StringType.SLB)
    elif c == StringType.SLL.value:
        return self._parse_literal_string()
    elif c == BoolType.TRUE.value[0]:
        return self._parse_true()
    elif c == BoolType.FALSE.value[0]:
        return self._parse_false()
    elif c == "[":
        return self._parse_nested(self._parse_array)
    elif c == "{":
        return self._parse_nested(self._parse_inline_table)
    elif c in "+-" or self._peek(4) in {"+inf", "-inf", "inf", "+nan", "-nan", "nan"}:
        return self._parse_number(trivia=trivia)
    elif c in string.digits:
        return self._parse_numeric_value(trivia=trivia)
    else:
        raise self.parse_error(UnexpectedCharError, c)

def _parse_number(self, trivia: Trivia) -> Item:
    self._src.advance_until(_NUM_STOP)
    raw = self.extract()

    m = RFC_3339_LOOSE.match(raw)
    if m:
        if m.group("date") and m.group("time"):
            return self._parse_datetime(raw, trivia)
        elif m.group("date"):
            return self._parse_date_and_time(raw, trivia)
        elif m.group("time"):
            return Time(*parse_rfc3339(raw).timetuple()[:6], trivia=trivia, raw=raw)

    item = self._parse_integer_or_float(raw, trivia)
    if item is not None:
        return item

    raise self.parse_error(InvalidNumberError)

def _parse_datetime(self, raw: str, trivia: Trivia) -> DateTime:
    dt = parse_rfc3339(raw)
    return DateTime(
        dt.year,
        dt.month,
        dt.day,
        dt.hour,
        dt.minute,
        dt.second,
        dt.microsecond,
        dt.tzinfo,
        trivia,
        raw,
    )

def _parse_date_and_time(self, raw: str, trivia: Trivia) -> DateTime:
    dt = parse_rfc3339(raw)
    date = Date(dt.year, dt.month, dt.day, trivia, raw)
    self.mark()
    self._src.advance_until(_DATE_TAIL_STOP)
    time_raw = self.extract()
    time_part = time_raw.rstrip()
    trivia.comment_ws = time_raw[len(time_part):]
    if not time_part:
        return date

    dt = parse_rfc3339(raw + time_part)
    return DateTime(
        dt.year,
        dt.month,
        dt.day,
        dt.hour,
        dt.minute,
        dt.second,
        dt.microsecond,
        dt.tzinfo,
        trivia,
        raw + time_part,
    )

def _parse_numeric_value(self, trivia: Trivia) -> Item:
    self._src.advance_until(_NUM_STOP)
    raw = self.extract()
    item = self._parse_integer_or_float(raw, trivia)
    if item is not None:
        return item
    raise self.parse_error(InvalidNumberError)

def _parse_integer_or_float(self, raw: str, trivia: Trivia) -> Item | None:
    try:
        return Integer(int(raw), trivia, raw)
    except ValueError:
        pass
    try:
        return Float(float(raw), trivia, raw)
    except ValueError:
        return None
