def _parse_value(self) -> Item:
    """
    Attempts to parse a value at the current position.
    """
    self.mark()
    c = self._current
    trivia = Trivia()

    if c == StringType.SLB.value:
        with self._state:
            return self._parse_string(StringType.SLB)
    elif c == StringType.SLL.value:
        return self._parse_literal_string()
    elif c == BoolType.TRUE.value[0]:
        return self._parse_true()
    elif c == BoolType.FALSE.value[0]:
        return self._parse_false()
    elif c == "[":
        return self._parse_nested(self._parse_array)
    elif c == "{":
        return self._parse_nested(self._parse_inline_table)
    elif c in "+-" or self._peek(4) in {
        "+inf",
        "-inf",
        "inf",
        "+nan",
        "-nan",
        "nan",
    }:
        # Number
        self._src.advance_until(_NUM_STOP)
        raw = self.extract()
        return self._parse_number(raw, trivia) or self.parse_error(InvalidNumberError)
    elif c in string.digits:
        # Integer, Float, Date, Time or DateTime
        self._src.advance_until(_NUM_STOP)
        raw = self.extract()
        m = RFC_3339_LOOSE.match(raw)
        if m:
            if m.group("date") and m.group("time"):
                return self._parse_datetime(raw)
            elif m.group("date"):
                return self._parse_date(raw)
            elif m.group("time"):
                return self._parse_time(raw)
        return self._parse_number(raw, trivia) or self.parse_error(InvalidNumberError)
    else:
        raise self.parse_error(UnexpectedCharError, c)

def _parse_datetime(self, raw: str) -> DateTime:
    dt = parse_rfc3339(raw)
    return DateTime(
        dt.year,
        dt.month,
        dt.day,
        dt.hour,
        dt.minute,
        dt.second,
        dt.microsecond,
        dt.tzinfo,
        Trivia(),
        raw,
    )

def _parse_date(self, raw: str) -> Date:
    dt = parse_rfc3339(raw)
    return Date(dt.year, dt.month, dt.day, Trivia(), raw)

def _parse_time(self, raw: str) -> Time:
    t = parse_rfc3339(raw)
    return Time(
        t.hour,
        t.minute,
        t.second,
        t.microsecond,
        t.tzinfo,
        Trivia(),
        raw,
    )
