def check_partial(sig, args, kwargs):
    """Like `is_partial_args` for the given signature spec."""
    num_pos_only, func, keyword_exclude, sigspec = sig

    # Pad args with None if they are fewer than positional-only arguments
    if len(args) < num_pos_only:
        args += (None,) * (num_pos_only - len(args))

    # Remove excluded keywords from kwargs
    if keyword_exclude:
        kwargs = {key: value for key, value in kwargs.items() if key not in keyword_exclude}

    # Check the signature specification
    sigspec2, result = _check_sigspec(sigspec, func, _sigs._is_partial_args, func, args, kwargs)
    if sigspec2 is None:
        return result

    # Try to bind partial arguments
    try:
        sigspec2.bind_partial(*args, **kwargs)
    except TypeError:
        return False

    return True
