import itertools

def interpose(el, seq):
    """ Introduce element between each pair of elements in seq

    >>> list(interpose("a", [1, 2, 3]))
    [1, 'a', 2, 'a', 3]
    >>> list(interpose("a", []))
    []
    """
    if not seq:
        return iter([])

    def intersperse():
        for item in seq[:-1]:
            yield item
            yield el
        yield seq[-1]

    return intersperse()
