import time

def get_link_or_missing(cache, key, timer=time.time):
    try:
        link = cache.__links[key]
        cache.__links.move_to_end(key)
    except KeyError:
        return None, True
    expired = not (timer() < link.expires)
    return link, expired

def __getitem__(self, key, cache_getitem=Cache.__getitem__):
    link, expired = get_link_or_missing(self, key)
    if expired:
        return self.__missing__(key)
    else:
        return cache_getitem(self, key)
