class _MethodDescriptor:
    ...

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self._get_unbound()
        elif self.__attrname is not None:
            return self._replace_descriptor_with_wrapper(obj)
        elif self.__deprecated:
            return self.Wrapper(obj)  # type: ignore
        else:
            raise TypeError("Cannot use @cachedmethod instance without calling __set_name__ on it")

