def generator(self) -> cabc.Iterator[V]:
    """Return a generator which yields the items added to the bar
    during construction, and updates the progress bar *after* the
    yielded block returns.
    """
    if not self.entered:
        raise RuntimeError("You need to use progress bars in a with block.")

    if not self._is_atty:
        yield from self.iter
    else:
        for rv in self.iter:
            self.current_item = rv

            if self._should_update():
                self.render_progress()

            yield rv
            self._reset_current_item()
            self._increment_completed_intervals()

            if self._should_render():
                self.make_step(self._completed_intervals)
                self.render_progress()
                self._reset_completed_intervals()

        self.finish()
        self.render_progress()

    def _should_update(self) -> bool:
        return self._completed_intervals == 0

    def _reset_current_item(self):
        self.current_item = None

    def _increment_completed_intervals(self):
        self._completed_intervals += 1

    def _should_render(self) -> bool:
        return self._completed_intervals >= self.update_min_steps
