import re
from typing import Match, Optional
from mistune.helpers import unescape_char

class BlockParser(Parser[BlockState]):
    ...

    def parse_fenced_code(self, m: Match[str], state: BlockState) -> Optional[int]:
        """Parse token for fenced code block. A fenced code block is started with
        3 or more backtick(`) or tilde(~).

        An example of a fenced code block:

        .. code-block:: markdown

            ```python
            def markdown(text):
                return mistune.html(text)
            ```
        """
        spaces = m.group("fenced_1")
        marker = m.group("fenced_2")
        info = m.group("fenced_3")

        if self._is_invalid_info_string(info, marker[0]):
            return None

        end_pattern = self._create_end_pattern(marker)
        cursor_start = m.end() + 1

        end_match = end_pattern.search(state.src, cursor_start)
        if end_match:
            code = state.src[cursor_start : end_match.start()]
            end_pos = end_match.end()
        else:
            code = state.src[cursor_start:]
            end_pos = state.cursor_max

        trimmed_code = self._trim_code(code, spaces)

        token = {
            "type": "block_code",
            "raw": trimmed_code,
            "style": "fenced",
            "marker": marker,
        }
        if info:
            token["attrs"] = {"info": unescape_char(info).strip()}

        state.append_token(token)
        return end_pos

    def _is_invalid_info_string(self, info: str, marker_char: str) -> bool:
        if info and marker_char == "`":
            return info.find("`") != -1
        return False

    def _create_end_pattern(self, marker: str) -> re.Pattern:
        mlen = len(marker)
        return re.compile(
            r"^ {0,3}" + marker[0] + "{" + str(mlen) + r",}[ \t]*(?:\n|$)", re.M
        )

    def _trim_code(self, code: str, spaces: str) -> str:
        if spaces and code:
            trim_pattern = re.compile("^ {0," + str(len(spaces)) + "}", re.M)
            return trim_pattern.sub("", code)
        return code
