        return parts[0] if len(parts) > 0 else None

    def _render_pre_tag(self, code: str, attrs: Dict[str, object]) -> str:
        attr_str = self.render_attrs(attrs)
        escaped_code = escape_text(code)
        return f"<pre{attr_str}>\n<code>{escaped_code}</code>\n</pre>"
