from ..core import BaseRenderer, BlockState
from ..util import strip_end
from ._list import render_list_item
from mistune.renderers._list import _render_ordered_list
from mistune.renderers._list import _render_unordered_list

# ...

class MarkdownRenderer(BaseRenderer):
    ...

    def list(self, token: Dict[str, Any], state: BlockState) -> str:
        children = self._render_list_items(token, state)
        text = ''.join(children)
        if token.get('parent') and not token['parent']['tight']:
            text += '\n'
        return strip_end(text) + '\n'

    def _render_list_items(self, token: Dict[str, Any], state: BlockState) -> Iterable[str]:
        if token['attrs']['ordered']:
            for item in token['children']:
                yield from self._render_ordered_list_item(item, state)
        else:
            for item in token['children']:
                yield from self._render_unordered_list_item(item, state)

    def _render_ordered_list_item(self, item: Dict[str, Any], state: BlockState) -> Iterable[str]:
        start = item['attrs'].get('start', 1)
        for child in item['children']:
            leading = f"{start}{item['bullet']} "
            child['parent'] = {'leading': leading, 'tight': item['tight']}
            try:
                yield render_list_item(self, child, state)
            finally:
                child.pop('parent', None)
                start += 1

    def _render_unordered_list_item(self, item: Dict[str, Any], state: BlockState) -> Iterable[str]:
        parent = {'leading': item['bullet'] + ' ', 'tight': item['tight']}
        for child in item['children']:
            child['parent'] = parent
            try:
                yield render_list_item(self, child, state)
            finally:
                child.pop('parent', None)
