import time
import os
from pathlib import Path

def _remove_cache_and_update_lock(cache_path=None):
    cache_path = cache_path or _default_cache_path
    lock_path = cache_path.joinpath('PARSO-CACHE-LOCK')

    if _should_clear_cache(lock_path):
        if _acquire_lock(lock_path):
            _clear_inactive_cache(cache_path)
            return True
    return False

def _should_clear_cache(lock_path):
    try:
        clear_lock_time = os.path.getmtime(lock_path)
    except FileNotFoundError:
        clear_lock_time = None
    return clear_lock_time is None or clear_lock_time + _CACHE_CLEAR_THRESHOLD <= time.time()

def _acquire_lock(lock_path):
    try:
        with open(lock_path, 'w'):
            pass
        return True
    except IOError:
        return False

def _clear_inactive_cache(cache_path):
    for dirname in os.listdir(cache_path):
        version_path = cache_path.joinpath(dirname)
        if version_path.is_dir():
            for file in os.scandir(version_path):
                if file.stat().st_atime + _CACHED_FILE_MAXIMUM_SURVIVAL <= time.time():
                    try:
                        os.remove(file.path)
                    except OSError:
                        continue
