    try:
        clear_lock_time = os.path.getmtime(lock_path)
    except FileNotFoundError:
        clear_lock_time = None

    return clear_lock_time is None or clear_lock_time + _CACHE_CLEAR_THRESHOLD <= time.time()

def _create_or_refresh_lock(lock_path: Path):
    if not _touch(lock_path):
        # Ensure no other cleanup job starts immediately.
        return False
    return True

def _touch(path: Path) -> bool:
    try:
        path.touch(exist_ok=False)
        return True
    except FileExistsError:
        return False
