    def __init__(self, node, lines, change_time):
        self.node = node
        self.lines = lines
        self.change_time = change_time
        self.last_used = time.time()

_CACHED_SIZE_TRIGGER = 1000
_CACHED_FILE_MINIMUM_SURVIVAL = 600  # 10 minutes in seconds
LOG = logging.getLogger(__name__)

def _garbage_collect_old_cache_items(parser_cache):
    cutoff_time = time.time() - _CACHED_FILE_MINIMUM_SURVIVAL
    for key, path_to_item_map in parser_cache.items():
        parser_cache[key] = {
            path: node_item
            for path, node_item in path_to_item_map.items()
            if node_item.last_used > cutoff_time
        }

def _get_hashed_path(hashed_grammar, path, cache_path=None):
    hash_object = hashlib.sha256(hashed_grammar.encode()).hexdigest()
    filename = f"{hash_object}_{os.path.basename(path)}"
    if cache_path:
        return os.path.join(cache_path, filename)
    return os.path.join(os.path.expanduser("~/.cache/parso"), filename)

def _remove_cache_and_update_lock(cache_path=None):
    lock_path = _get_hashed_path(None, "lock", cache_path=cache_path)
    if os.path.exists(lock_path):
        os.remove(lock_path)

def try_to_save_module(hashed_grammar, file_io, module, lines, pickling=True, cache_path=None):
    path = file_io.path
    try:
        p_time = None if path is None else file_io.get_last_modified()
    except OSError:
        p_time = None
        pickling = False

    item = _NodeCacheItem(module, lines, p_time)
    path2 = path
    if sum((len(v) for v in parser_cache.values())) >= _CACHED_SIZE_TRIGGER:
        _garbage_collect_old_cache_items(parser_cache)

    parser_cache.setdefault(hashed_grammar, {})[path2] = item

    if pickling and path is not None:
        try:
            _save_to_file_system(hashed_grammar, path, item, cache_path=cache_path)
        except PermissionError:
            warnings.warn(
                'Tried to save a file to %s, but got permission denied.' % path,
                Warning
            )
        else:
            _remove_cache_and_update_lock(cache_path=cache_path)
