            _save_to_file_system(hashed_grammar, path, item, cache_path=cache_path)
        except PermissionError:
            warnings.warn(
                'Tried to save a file to %s, but got permission denied.' % path,
                Warning
            )

def _update_cache(hashed_grammar, path, item):
    if sum((len(v) for v in parser_cache.values())) >= _CACHED_SIZE_TRIGGER:
        cutoff_time = time.time() - _CACHED_FILE_MINIMUM_SURVIVAL
        parser_cache[hashed_grammar] = {
            path: node_item
            for path, node_item in parser_cache[hashed_grammar].items()
            if node_item.last_used > cutoff_time
        }
    parser_cache.setdefault(hashed_grammar, {})[path] = item
