def _parse_atom(self):
    # atom: '(' rhs ')' | NAME | STRING
    if self.value == "(":
        return self._parse_parenthesized_expression()
    elif self.type in (PythonTokenTypes.NAME, PythonTokenTypes.STRING):
        return self._parse_terminal()
    else:
        self._raise_error("expected (...) or NAME or STRING, got %s/%s",
                          self.type, self.value)

def _parse_parenthesized_expression(self):
    self._gettoken()
    a, z = self._parse_rhs()
    self._expect(PythonTokenTypes.OP, ')')
    return a, z

def _parse_terminal(self):
    a = NFAState(self._current_rule_name)
    z = NFAState(self._current_rule_name)
    a.add_arc(z, self.value)
    self._gettoken()
    return a, z
