def _reset_newlines(self, spacing, leaf, is_comment=False):
    self._update_max_new_lines_in_prefix()

    if self._wanted_newline_count is not None:
        self._check_and_update_blank_lines(spacing, leaf, is_comment)
        self._wanted_newline_count = None

    if not is_comment:
        self._check_and_add_blank_line_issues(leaf)

    self._newline_count = 0

def _update_max_new_lines_in_prefix(self):
    self._max_new_lines_in_prefix = max(self._max_new_lines_in_prefix, self._newline_count)

def _check_and_update_blank_lines(self, spacing, leaf, is_comment):
    blank_lines = self._newline_count - 1
    if self._wanted_newline_count > blank_lines and leaf.type != 'endmarker':
        if not is_comment:
            self._add_blank_line_issue(spacing, self._wanted_newline_count, blank_lines)
            self._wanted_newline_count = None

def _check_and_add_blank_line_issues(self, leaf):
    suite_node = self._indentation_tos.get_latest_suite_node()
    wanted = int(suite_node.parent is None) + 1
    actual = self._max_new_lines_in_prefix - 1

    if self._needs_blank_lines(leaf.value, leaf.parent, suite_node) and actual < wanted:
        self._add_blank_line_issue(None, wanted, actual)

def _needs_blank_lines(self, value, parent, suite_node):
    return (
        value == '@' and parent.type == 'decorator'
        or (
            value == 'class'
            or value == 'async' and parent.get_next_leaf() == 'def'
            or value == 'def' and self._previous_leaf != 'async'
        ) and parent.parent.type != 'decorated'
    )

def _add_blank_line_issue(self, spacing, wanted, actual):
    code = 302 if wanted == 2 else 301
    message = f"expected {wanted} blank line, found {actual}"
    if spacing:
        self.add_issue(spacing, code, message)
    else:
        self.add_issue(self._previous_part, code, message)
