def _parse_attribute_specifier_sequence(self) -> list[c_ast.AttributeSpecifier]:
    groups = []
    while self._has_next_token_of_type("ATTRIBUTE_BEGIN"):
        opening = self._next_token()
        if self._dialect != "c23":
            self._parse_error("Attributes require C23", self._tok_coord(opening))

        attributes = self._parse_attributes_until("ATTRIBUTE_END")

        groups.append(c_ast.AttributeSpecifier(attributes, self._tok_coord(opening)))

    return groups

def _has_next_token_of_type(self, token_type: str) -> bool:
    return self._peek_type() == token_type

def _next_token(self) -> Token:
    tok = self._tokens.next()
    if tok is None:
        self._parse_error('At end of input', self.clex.filename)
    if tok is not self._typedef_checked_token:
        self._classify_identifier(tok)
    return tok

def _parse_attributes_until(self, end_token_type: str) -> list[c_ast.Attribute]:
    attributes = []
    while not self._has_next_token_of_type(end_token_type):
        if self._accept("COMMA"):
            continue

        name = self._parse_identifier_or_typeid()
        namespace = None
        if self._accept("COLONCOLON"):
            namespace = name.name
            name = self._parse_identifier_or_typeid()

        arguments = self._accept("ATTRIBUTE_ARGUMENTS")
        attributes.append(
            c_ast.Attribute(
                name.name,
                namespace,
                arguments.value if arguments is not None else None,
                name.coord,
            )
        )

        if not self._accept("COMMA"):
            break

    self._expect(end_token_type)
    return attributes
