@dataclass(frozen=True)
class ParamListBuilder:
    initial_token: Token
    param_factory: Callable[[], c_ast.Node]

    @classmethod
    def from_first_param(cls, first_param: c_ast.Node):
        return cls(initial_token=first_param.coord, param_factory=lambda: first_param)

    def add_params(self, parser: 'CParser') -> c_ast.ParamList:
        params = c_ast.ParamList([self.param_factory()], self.initial_token)
        while parser._accept('COMMA'):
            params.params.append(parser._parse_identifier())
        return params
