def _parse_parameter_type_list(self) -> c_ast.ParamList:
    params = []
    ellipsis_found = False

    while True:
        if self._peek_type() == "ELLIPSIS":
            if ellipsis_found:
                self._parse_error("Multiple ellipses in parameter list", self._tok_coord(self._peek_token()))
            ellipsis_found = True
            ell_tok = self._advance()
            params.append(c_ast.EllipsisParam(self._tok_coord(ell_tok)))
            break  # Only one ellipsis allowed per parameter list
        else:
            params.append(self._parse_parameter_declaration())

        if self._peek_type() != "COMMA":
            break
        self._advance()

    return c_ast.ParamList(params, params[0].coord if params else None)
