def _parse_typeof_specifier(self) -> c_ast.TypeOf:
    tok = self._advance()
    self._expect("LPAREN")

    if self._starts_declaration():
        expr = self._parse_type_name()
    else:
        expr = self._parse_expression()

    self._expect("RPAREN")
    return c_ast.TypeOf(tok.value, expr, self._tok_coord(tok))
