def check(codeString, filename, reporter=None):
    """
    Check the Python source given by C{codeString} for flakes.

    @param codeString: The Python source to check.
    @type codeString: C{str}

    @param filename: The name of the file the source came from, used to report
        errors.
    @type filename: C{str}

    @param reporter: A L{Reporter} instance, where errors and warnings will be
        reported.

    @return: The number of warnings emitted.
    @rtype: C{int}
    """
    if reporter is None:
        reporter = modReporter._makeDefaultReporter()

    try:
        tree = parse_code_string(codeString, filename)
    except SyntaxError as e:
        reporter.syntaxError(filename, e.msg, e.lineno, e.offset, e.text)
        return 1
    except Exception:
        reporter.unexpectedError(filename, 'problem decoding source')
        return 1

    w = checker.Checker(tree, filename=filename)
    w.messages.sort(key=lambda m: m.lineno)
    for warning in w.messages:
        reporter.flake(warning)

    return len(w.messages)


def parse_code_string(codeString, filename):
    """
    Parse the given Python source string into an AST.

    @param codeString: The Python source to parse.
    @type codeString: C{str}

    @param filename: The name of the file the source came from.
    @type filename: C{str}

    @return: The parsed AST.
    @rtype: C{ast.AST}
    """
    try:
        return ast.parse(codeString, filename=filename)
    except SyntaxError as e:
        raise
    except Exception as e:
        raise Exception(f"Problem decoding source: {e}") from e
