def _lookup_style(style):
    if isinstance(style, str):
        return _find_builtin_or_plugin_style(style)
    return style

def _find_builtin_or_plugin_style(style_name):
    if style_name in _STYLE_NAME_TO_MODULE_MAP:
        return _import_style_from_module(style_name, _STYLE_NAME_TO_MODULE_MAP[style_name])

    for found_name, style_class in find_plugin_styles():
        if style_name == found_name:
            return style_class

    return _import_style_from_module(style_name, ('pygments.styles.', style_name.title() + 'Style'))

def _import_style_from_module(style_name, module_info):
    mod, cls = module_info
    try:
        mod = __import__(mod, None, None, [cls])
    except ImportError as e:
        raise ClassNotFound(f'Could not find style module {mod!r}') from e
    try:
        return getattr(mod, cls)
    except AttributeError as e:
        raise ClassNotFound(f'Could not find style class {cls!r} in style module.') from e
