def _find_style_by_name(style):
    if style in _STYLE_NAME_TO_MODULE_MAP:
        mod, cls = _STYLE_NAME_TO_MODULE_MAP[style]
        return _load_style_module(mod, cls, 'yes')

    for found_name, style2 in find_plugin_styles():
        if style == found_name:
            return style2

    builtin = ''
    mod = 'pygments.styles.' + style
    cls = style.title() + 'Style'

    return _load_style_module(mod, cls, builtin)

def _load_style_module(mod, cls, builtin):
    try:
        mod = __import__(mod, None, None, [cls])
    except ImportError:
        raise ClassNotFound(f'Could not find style module {mod!r}' + (builtin and ', though it should be builtin') + '.')

    try:
        return getattr(mod, cls)
    except AttributeError:
        raise ClassNotFound(f'Could not find style class {cls!r} in style module.')
