class RawTokenFormatter(Formatter):
    def __init__(self, **options):
        super().__init__(**options)
        self.encoding = 'ascii'  # Ensure ASCII encoding for raw token output
        self.compress = get_choice_opt(options, 'compress', ['', 'none', 'gz', 'bz2'], '')
        self.error_color = options.get('error_color', None)

        if self.error_color is True:
            self.error_color = 'red'

        if self.error_color is not None:
            self.validate_error_color()

    def validate_error_color(self):
        try:
            color_key = self.error_color
            colorize(color_key, '') + codes['reset']
        except KeyError:
            raise ValueError(f"Invalid color {self.error_color!r} specified")
