def reset_string(self):
    """Reset terminal attributes to default."""
    reset_attrs = []

    if self.fg is not None:
        reset_attrs.append("39")  # Reset foreground color

    if self.bg is not None:
        reset_attrs.append("49")  # Reset background color

    if self.bold or self.underline or self.italic:
        reset_attrs.append("00")  # Reset all text effects

    if reset_attrs:
        return f"\x1b[{';'.join(reset_attrs)}m"
    return ""
