def _color_index(self, color):
    if color in self.best_match:
        return self.best_match[color]

    if color in ansicolors:
        index = color
    else:
        rgb = self._color_tuple(color)
        if rgb is None:
            rgb = (0, 0, 0)

        index = self._find_closest_color(*rgb)

    self.best_match[color] = index
    return index

def _color_tuple(self, color):
    try:
        rgb = int(str(color), 16)
    except ValueError:
        return None
    r = (rgb >> 16) & 0xff
    g = (rgb >> 8) & 0xff
    b = rgb & 0xff
    return (r, g, b)

def _find_closest_color(self, r, g, b):
    best_distance = float('inf')
    closest_index = 0

    for i, values in enumerate(self.xterm_colors):
        rd = r - values[0]
        gd = g - values[1]
        bd = b - values[2]
        distance = rd * rd + gd * gd + bd * bd

        if distance < best_distance:
            best_distance = distance
            closest_index = i

    return closest_index
