def _append_multiline_row(
    lines, padded_multiline_cells, padded_widths, colaligns, rowfmt, pad, rowalign=None
):
    colwidths = [w - 2 * pad for w in padded_widths]
    cells_lines = [c.splitlines() for c in padded_multiline_cells]
    nlines = max(map(len, cells_lines))

    cells_lines = [
        _align_cell_veritically(cl, nlines, w, rowalign) for cl, w in zip(cells_lines, colwidths)
    ]
    lines_cells = [[cl[i] for cl in cells_lines] for i in range(nlines)]

    for ln in lines_cells:
        padded_ln = _pad_row(ln, pad)
        lines.append(_build_row(padded_ln, colwidths, colaligns, rowfmt))

    return lines


def _align_cell_veritically(cell_lines, nlines, colwidth, rowalign):
    if rowalign == "top":
        return cell_lines + [" "] * (nlines - len(cell_lines))
    elif rowalign == "middle":
        top_padding = (nlines - len(cell_lines)) // 2
        bottom_padding = nlines - len(cell_lines) - top_padding
        return [" "] * top_padding + cell_lines + [" "] * bottom_padding
    elif rowalign == "bottom":
        return [" "] * (nlines - len(cell_lines)) + cell_lines
    else:
        return cell_lines
