from typing import Iterator, Union
from io import IO, TextIOWrapper
import sys

from sqlparse.engine import grouping
from sqlparse.engine.statement_splitter import StatementSplitter
from sqlparse.exceptions import SQLParseError
from sqlparse.filters import (
    StripTrailingSemicolonFilter,
    StripCommentsFilter,
    SpacesAroundOperatorsFilter,
)
from sqlparse.lexer import Lexer
from sqlparse.sql import Statement

class FilterStack:
    def __init__(self):
        self.preprocess = []
        self.stmtprocess = []
        self.postprocess = []
        self._grouping = False

    def enable_grouping(self):
        self._grouping = True

    def add_filter(self, filter_, position='post'):
        if position == 'pre':
            self.preprocess.append(filter_)
        elif position == 'stmt':
            self.stmtprocess.append(filter_)
        elif position == 'post':
            self.postprocess.append(filter_)

    def run(self, sql: Union[str, IO[str]], encoding: str = None) -> Iterator[Statement]:
        try:
            stream = Lexer.get_default_instance().get_tokens(sql, encoding)
            stream = self.apply_filters(stream, self.preprocess)

            stream = StatementSplitter().process(stream)

            for stmt in stream:
                if self._grouping:
                    stmt = grouping.group(stmt)

                stmt = self.apply_filters(stmt, self.stmtprocess)

                stmt = self.apply_filters(stmt, self.postprocess)

                yield stmt
        except RecursionError as err:
            raise SQLParseError('Maximum recursion depth exceeded') from err

    def apply_filters(self, item, filters):
        for filter_ in filters:
            if isinstance(item, list):
                item = [filter_.process(subitem) for subitem in item]
            else:
                item = filter_.process(item)
        return item
