from io import IO
from sqlparse import sql
from sqlparse.engine import grouping
from sqlparse.engine.statement_splitter import StatementSplitter
from sqlparse.exceptions import SQLParseError
from sqlparse.filters import StripTrailingSemicolonFilter
from sqlparse.lexer import Lexer

class FilterStack:
    def __init__(self):
        self.preprocess = []
        self.stmtprocess = []
        self.postprocess = []
        self._grouping = False

    def enable_grouping(self):
        self._grouping = True

    def add_filter(self, filter_, position='post'):
        if position == 'pre':
            self.preprocess.append(filter_)
        elif position == 'stmt':
            self.stmtprocess.append(filter_)
        elif position == 'post':
            self.postprocess.append(filter_)

    def run(self, sql: Union[str, IO[str]], encoding: str = None) -> Iterator[sql.Statement]:
        try:
            stream = Lexer.get_default_instance().get_tokens(sql, encoding)
            stream = self.apply_filters(stream, self.preprocess)
            stream = StatementSplitter().process(stream)
            stream = self.apply_filters(stream, self.stmtprocess)
            stream = self.apply_filters(stream, self.postprocess, transform=self.transform_stmt)
            for stmt in stream:
                yield stmt
        except RecursionError as err:
            raise SQLParseError('Maximum recursion depth exceeded') from err

    def apply_filters(self, stream, filters, transform=None):
        for filter_ in filters:
            stream = filter_.process(stream)
        if transform:
            stream = map(transform, stream)
        return stream

    @staticmethod
    def transform_stmt(stmt):
        if isinstance(stmt, sql.Grouped):
            stmt = grouping.group(stmt)
        return stmt
