def token_next(self, idx, skip_ws=True, skip_cm=False, _reverse=False):
    """Returns the next token relative to *idx*.

    If *skip_ws* is ``True`` (the default) whitespace tokens are ignored.
    If *skip_cm* is ``True`` comments are ignored.
    ``None`` is returned if there's no next token.
    """
    if idx is None:
        return None, None

    def should_skip_token(token):
        return (skip_ws and token.is_whitespace) or (skip_cm and imt(token, t=T.Comment, i=Comment))

    if _reverse:
        start_index = max(0, idx - 2)
        step = -1
    else:
        start_index = idx + 1
        step = 1

    for index in range(start_index, len(self.tokens), step):
        token = self.tokens[index]
        if not should_skip_token(token):
            return index, token

    return None, None
