    if idx is None:
        return None, None

    def should_skip_token(token):
        return (skip_ws and token.is_whitespace) or (skip_cm and imt(token, t=T.Comment))

    if _reverse:
        return self._find_next_token(idx, should_skip_token, step=-1)
    else:
        return self._find_next_token(idx, should_skip_token)

def _find_next_token(self, idx, should_skip_token, step=1):
    """Helper function to find the next non-skipped token."""
    start = idx + step
    end = len(self.tokens) if step > 0 else -1
    step_range = range(start, end, step)

    for idx2 in step_range:
        token = self.tokens[idx2]
        if not should_skip_token(token):
            return idx2, token

    return None, None
