        """Returns the next token relative to *idx*.

        If *skip_ws* is ``True`` (the default) whitespace tokens are ignored.
        If *skip_cm* is ``True comments are ignored.
        ``None`` is returned if there's no next token.
        """
        if idx is None:
            return None, None
        idx += 1  # alot of code usage current pre-compensates for this

        matcher = create_token_matcher(skip_ws, skip_cm)
        funcs = (matcher,)
        end = None
        if idx is None:
            return None
        if not isinstance(funcs, (list, tuple)):
            funcs = (funcs,)
        if _reverse:
            assert end is None
            indexes = range(idx - 2, -1, -1)
        else:
            if end is None:
                end = len(self.tokens)
            indexes = range(idx, end)
        for idx2 in indexes:
            token = self.tokens[idx2]
            for func in funcs:
                if func(token):
                    return (idx2, token)
        return (None, None)
