def _create_token_match_functions(self, i, m, t):
    if i is not None and m is not None and t is not None:
        return [lambda tk, i=i, m=m, t=t: imt(tk, i, m, t)]
    elif i is not None and m is not None:
        return [lambda tk, i=i, m=m: imt(tk, i, m)]
    elif i is not None and t is not None:
