    elif m is not None and t is not None:
        return [lambda tk, m=m, t=t: imt(tk, m, t)]
    elif i is not None:
        return [lambda tk, i=i: imt(tk, i)]
    elif m is not None:
        return [lambda tk, m=m: imt(tk, m)]
    elif t is not None:
