def __setitem__(self, key: Key | str, value: Any) -> None:
    if key in self:
        self._update_existing_key(key, value)
    else:
        self._add_new_key(key, value)

def _update_existing_key(self, key: Key | str, value: Any) -> None:
    old_key = next(filter(lambda k: k == key, self._map))
    key2 = old_key if isinstance(old_key, Key) else SingleKey(old_key)
    idx = self._map.get(key2)
    if idx is None:
        raise NonExistentKey(key2)
    self._replace_at(idx, key, value)

def _add_new_key(self, key: Key | str, value: Any) -> None:
    key2 = key if isinstance(key, Key) else SingleKey(key)
    self.append(key2, value)
