from tomlkit.exceptions import NonExistentKey
from tomlkit.items import SingleKey
from tomlkit.items import item as _item

def _replace_at(self, idx: int, new_key: Key | str, value: Item) -> None:
    if not isinstance(new_key, Key):
        new_key = SingleKey(new_key)

    value = _item(value)

    if idx > 0:
        previous_item = self._body[idx - 1][1]
        if not (
            isinstance(previous_item, Whitespace)
            or ends_with_whitespace(previous_item)
            or isinstance(value, (AoT, Table))
            or "\n" in previous_item.trivia.trail
        ):
            previous_item.trivia.trail += "\n"

    # Increment indices after the current index
    for k, v in self._map.items():
        if isinstance(v, tuple):
            new_indices = []
            for v_ in v:
                if v_ >= idx:
                    v_ = v_ + 1

                new_indices.append(v_)

            self._map[k] = tuple(new_indices)
        elif v >= idx:
            self._map[k] = v + 1

    if new_key in self._map:
        current_idx = self._map[new_key]
        if not isinstance(current_idx, tuple):
            current_idx = (current_idx,)
        self._map[new_key] = (*current_idx, idx)
        self._out_of_order_keys.add(new_key)
    else:
        self._map[new_key] = idx
    self._body[idx] = (new_key, value)

    dict.__setitem__(self, new_key.key, value.value)

def __setitem__(self, key: Key | str, value: Any) -> None:
    if key in self:
        old_key = next(filter(lambda k: k == key, self._map))
        key2 = old_key
        if not isinstance(key2, Key):
            key2 = SingleKey(key2)
        idx = self._map.get(key2)
        if idx is None:
            raise NonExistentKey(key2)
        self._replace_at(idx, key, value)
    else:
        self.append(key, value)
