    self._update_tables_map_after_deletion(_key)
    self._internal_container.__delitem__(key)
    if key is not None:
        dict.__delitem__(self, key)

def _remove_table(self, table: Table) -> None:
    """Remove table from the parent container"""
    self._tables.remove(table)
    for idx, body_item in enumerate(self._container._body):
        if body_item[1] is table:
            self._container._remove_at(idx)
            break

def _update_tables_map_after_deletion(self, key: Key) -> None:
    """Update the tables map after deleting a key"""
    if key in self._tables_map:
        del self._tables_map[key]
