from typing import Any
from typing import Optional

def insert(self, index: int, value: dict[str, Any]) -> None:  # type: ignore[override]
    value = item(value, _parent=self)
    if not isinstance(value, Table):
        raise ValueError(f"Unsupported insert value type: {type(value)}")

    length = len(self)
    adjusted_index = index if index >= 0 else length + index

    if adjusted_index < 0:
        adjusted_index = 0
    elif adjusted_index > length:
        adjusted_index = length

    self._adjust_indentation(adjusted_index, value)
    self._body.insert(adjusted_index, value)
    list.insert(self, adjusted_index, value)
    self._reindex()

def _adjust_indentation(self, index: int, value: Item) -> None:
    length = len(self)
    prev_table = self._body[index - 1] if 0 < index < length else None
    next_table = self._body[index] if index < length - 1 else None

    if not self._parsed:
        if prev_table and "\n" not in value.trivia.indent:
            value.trivia.indent = "\n" + value.trivia.indent
        if next_table and "\n" not in next_table.trivia.indent:
            next_table.trivia.indent = "\n" + next_table.trivia.indent

    if index < length:
        try:
            idx = self._index_map[index]
        except KeyError as e:
            raise IndexError("list index out of range") from e
    else:
        idx = len(self._value)
        if idx >= 1 and self._value[idx - 1].is_whitespace():
            idx -= 1

    indent: Optional[Whitespace] = None
    comma: Optional[Whitespace] = None
    if idx < len(self._value) and not self._value[idx].is_whitespace():
        indent = self._value[idx].indent
    if idx > 0:
        last_item = self._value[idx - 1]
        if indent is None:
            indent = last_item.indent
        if not isinstance(last_item.value, Null) and "\n" in self._trivia.indent:
            comma = last_item.comma
        comma_in_indent = indent is not None and "," in indent.s
        if (
            last_item.comma is None
            and not isinstance(last_item.value, Null)
            and not comma_in_indent
        ):
            last_item.comma = Whitespace(",")

    if indent is not None and "," in indent.s:
        comma = None
    if indent is None and (idx > 0 or "\n" in self._trivia.indent):
        indent = Whitespace("    ")

    new_item = _ArrayItemGroup(value=value, indent=indent, comma=comma)
    self._value.insert(idx, new_item)
