from typing import Any
from typing import Optional
from tomlkit.items import Array
from tomlkit.items import item
from tomlkit.items import _ArrayItemGroup
from tomlkit.exceptions import ValueError

def insert(self, pos: int, value: Any) -> None:  # type: ignore[override]
    it = item(value, _parent=self)
    if not isinstance(it, (Comment, Whitespace)):
        list.insert(self, pos, it)

    if pos < 0:
        pos += len(self)
        if pos < 0:
            pos = 0

    idx = find_insert_position(self, pos)
    indent, comma = determine_indent_and_comma(self, idx)

    new_item = _ArrayItemGroup(value=it, indent=indent, comma=comma)
    self._value.insert(idx, new_item)
    update_index_map(self)

def find_insert_position(array: Array, pos: int) -> int:
    length = len(array)
    if pos < 0:
        pos += length
        if pos < 0:
            pos = 0
    elif pos >= length:
        pos = length
    return pos

def determine_indent_and_comma(array: Array, idx: int) -> tuple[Optional[Whitespace], Optional[Whitespace]]:
    default_indent = " "
    if idx < len(array._value):
        try:
            idx = array._index_map[idx]
        except KeyError as e:
            raise IndexError("list index out of range") from e
    else:
        idx = len(array._value)
        if idx >= 1 and array._value[idx - 1].is_whitespace():
            idx -= 1
            _indent = array._value[idx].indent
            if _indent is not None and "\n" in _indent.s:
                default_indent = "\n    "

    indent: Optional[Whitespace] = None
    comma: Optional[Whitespace] = Whitespace(",") if idx < len(array._value) else None

    if idx < len(array._value) and not array._value[idx].is_whitespace():
        indent = array._value[idx].indent

    if idx > 0:
        last_item = array._value[idx - 1]
        if indent is None:
            indent = last_item.indent

        if not isinstance(last_item.value, Null) and "\n" in default_indent:
            comma = last_item.comma

        comma_in_indent = indent is not None and "," in indent.s
        if last_item.comma is None and not isinstance(last_item.value, Null) and not comma_in_indent:
            last_item.comma = Whitespace(",")

    if indent is not None and "," in indent.s:
        comma = None

    if indent is None and (idx > 0 or "\n" in default_indent):
        indent = Whitespace(default_indent)

    return indent, comma

def update_index_map(array: Array) -> None:
    array._index_map.clear()
    index = 0
    for i, v in enumerate(array._value):
        if v.value is None or isinstance(v.value, Null):
            continue
        array._index_map[index] = i
        index += 1
