class InlineTable(AbstractTable):
    ...

    def append(self, key: Optional[Key | str], _item: Any) -> InlineTable:
        """
        Appends a (key, item) to the table.
        """
        self._ensure_valid_item(_item)
        self._update_indentation(_item)
        self._add_to_value(key, _item)
        self._set_dict_item(key, _item)
        return self

    def _ensure_valid_item(self, _item: Any) -> None:
        if not isinstance(_item, Item):
            _item = item(_item, _parent=self)
        if isinstance(_item, Table):
            raise ValueError('Inline tables cannot contain a table')
        if not isinstance(_item, (Whitespace, Comment)):
            self._apply_default_indentation(_item)

    def _update_indentation(self, _item: Item) -> None:
        if not _item.trivia.indent and len(self._value) > 0 and not self._new:
            _item.trivia.indent = " "
        if _item.trivia.comment:
            _item.trivia.comment = ""

    def _add_to_value(self, key: Optional[Key | str], _item: Item) -> None:
        self._value.append(key, _item)

    def _set_dict_item(self, key: Optional[Key | str], _item: Item) -> None:
        if key is not None:
            key = key.key if isinstance(key, Key) else key
            dict.__setitem__(self, key, _item)

    def _apply_default_indentation(self, _item: Item) -> None:
        if not _item.trivia.indent and len(self._value) > 0 and not self._new:
            _item.trivia.indent = " "
