def _parse_key_value(self, parse_comment: bool = False) -> tuple[Key, Item]:
    # Leading indent
    indent = self._extract_indent()

    # Key
    key = self._parse_simple_key()
    key = self._parse_nested_keys(key)

    self._skip_whitespace_and_newlines()

    # Check for equals sign
    if self._current != '=':
        raise self.parse_error(UnexpectedCharError, self._current)

    self._consume_char('=')

    if not key.sep:
        key.sep = self._extract_separator()
    else:
        key.sep += self._extract_separator()

    # Value
    val = self._parse_value()

    # Comment
    if parse_comment:
        cws, comment, trail = self._parse_comment_trail()
        val.trivia.update_comment(cws, comment, trail)
    else:
        val.trivia.trail = ""

    val.trivia.indent = indent

    return key, val

def _extract_indent(self) -> str:
    self.mark()
    self._src.advance_while(_SPACES)
    return self.extract()

def _parse_nested_keys(self, key: Key) -> Key:
    fragments = 1
    while self._current == '.':
        fragments += 1
        if fragments > self.MAX_NESTING_DEPTH:
            raise self.parse_error(ParseError, f'TOML key nested more than {self.MAX_NESTING_DEPTH} levels deep')
        self.inc()
        key = key.concat(self._parse_simple_key())
    return key

def _skip_whitespace_and_newlines(self) -> None:
    self.mark()
    self._src.advance_while(" \t\n\r")
    self.inc()

def _extract_separator(self) -> str:
    self.mark()
    if not self.inc():
        raise self.parse_error(UnexpectedEofError)
    return self.extract()
