    """ Like ``is_partial_args`` for the given signature spec"""
    num_pos_only, func, keyword_exclude, sigspec = sig
    padded_args = pad_arguments(args, num_pos_only)
    filtered_kwargs = filter_keyword_arguments(kwargs, keyword_exclude)

    sigspec2, rv = _check_sigspec(sigspec, func, _sigs._is_partial_args, func, padded_args, filtered_kwargs)
    if sigspec2 is None:
        return rv

    try:
        sigspec2.bind_partial(*padded_args, **filtered_kwargs)
    except TypeError:
        return False

    return True

def pad_arguments(args, num_pos_only):
    if len(args) < num_pos_only:
        pad = (None,) * (num_pos_only - len(args))
        return args + pad
    return args

def filter_keyword_arguments(kwargs, keyword_exclude):
    if keyword_exclude:
        kwargs = dict(kwargs)
        for item in keyword_exclude:
            kwargs.pop(item, None)
    return kwargs
