    >>> dissoc({'x': 1}, 'y') # Ignores missing keys
    {'x': 1}
    """
    factory = _get_factory(dissoc, kwargs)
    d2 = factory()

    if len(keys) < len(d) * .6:
        d2.update(d)
        for key in keys:
            d2.pop(key, None)
    else:
        d2.update((k, v) for k, v in d.items() if k not in keys)
    return d2
