from typing import Callable, Dict, Any, TypeVar, Generic, Iterable

T = TypeVar('T')

class LazyList(Generic[T]):
    def __init__(self, initial_values: Iterable[T] = None):
        self._values = initial_values or []

    def append(self, value: T):
        self._values.append(value)

    def __call__(self) -> List[T]:
        return self._values

def merge_with(func: Callable[[Iterable[Any]], Any], *dicts: Dict[str, Any], **kwargs) -> Dict[str, Any]:
    """ Merge dictionaries and apply function to combined values

    A key may occur in more than one dict, and all values mapped from the key
    will be passed to the function as a list, such as func([val1, val2, ...]).

    >>> merge_with(sum, {1: 1, 2: 2}, {1: 10, 2: 20})
    {1: 11, 2: 22}

    >>> merge_with(first, {1: 1, 2: 2}, {2: 20, 3: 30})  # doctest: +SKIP
    {1: 1, 2: 2, 3: 30}

    See Also:
        merge
    """
    if len(dicts) == 1 and not isinstance(dicts[0], Mapping):
        dicts = dicts[0]
    factory2 = kwargs.pop('factory', dict)
    if kwargs:
        raise TypeError("{}() got an unexpected keyword argument '{}'".format(merge_with.__name__, kwargs.popitem()[0]))
    factory = factory2

    values = collections.defaultdict(LazyList)
    for d in dicts:
        for k, v in d.items():
            values[k].append(v)

    result = factory()
    for k, v in values.items():
        result[k] = func(v())
    return result
